<template><SuperAdminLayout><header><p>11. IMPORT FROM PAYMENT GATEWAY</p><h1>Payment Gateway Import</h1><small>Synchronize Stripe subscription invoices and payment results with the platform.</small></header><section class="card"><h2>Stripe Import</h2><p>This import retrieves the latest 100 Stripe invoices, matches them to customer Stripe IDs, and updates the billing and tax-report records.</p><button :disabled="loading" @click="run">{{loading?'Importing…':'Import Stripe Invoices'}}</button><p v-if="message" :class="error?'error':'success'">{{message}}</p></section><section class="card"><h2>Import Notes</h2><ul><li>Only invoices linked to an existing platform customer are imported.</li><li>Existing invoice records are updated, so repeat imports are safe.</li><li>Stripe must be configured in the application environment before importing.</li></ul></section></SuperAdminLayout></template>
<script setup>import{ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const loading=ref(false),message=ref(''),error=ref(false);const run=async()=>{loading.value=true;message.value='';error.value=false;try{const{data}=await client.post('/super-admin/payment-gateway/import');message.value=`Stripe import completed: ${data.data.imported} customer invoices synchronized from ${data.data.retrieved} retrieved invoices.`}catch(e){error.value=true;message.value=e?.response?.data?.message||'Import failed.'}finally{loading.value=false}}</script>
<style scoped>header{margin-bottom:20px}header p{margin:0;color:#2877ce;font-size:.72rem;font-weight:700;letter-spacing:.1em}h1{margin:5px 0;font-size:2rem}small,p,li{color:#64748b}.card{background:#fff;border:1px solid #e3e8f1;border-radius:9px;padding:20px;margin:16px 0;max-width:800px}.card h2{margin:0 0 10px;font-size:1.05rem}button{border:0;border-radius:6px;background:#156ad1;color:#fff;padding:11px 17px;font-weight:600}button:disabled{opacity:.6}.success{color:#167044}.error{color:#b42318}</style>
